const (
	noteNoContainer = "No running container — only this machine is offered"
	noteNoEngine    = "No Docker Engine reachable — only this machine is offered"
	noteDesktop     = "Docker Desktop is not supported as a container source yet"
	notePodman      = "podman is not supported as a container source"

	hostLabel          = "this machine"
	engineTextMaxRunes = 128
	dockerDesktopName  = "Docker Desktop"
)

// pathSource is where a path trace starts: this machine or a container.
type pathSource struct {
	ID    string // validated container ID; "" for this machine
	Name  string // display-safe
	Image string // display-safe
}

// hostSource returns the source that stands for this machine.
func hostSource() pathSource { return pathSource{} }

func (s pathSource) isHost() bool { return s.ID == "" }

// label is the text the selector and the table show for the source.
func (s pathSource) label() string {
	if s.isHost() {
		return hostLabel
	}
	return s.Name
}

// pathSourceList is what the selector offers besides this machine.
type pathSourceList struct {
	Containers []pathSource // running, sorted by Name; this machine is not in it
	Note       string       // why only this machine is offered; "" otherwise
}

// sourceListFrom builds the selector's list from what the engine answered.
// Precedence: podman, then any read error, then Docker Desktop, then the list.
func sourceListFrom(engineName, osName string, osErr error, cs []docker.Container, psErr error) pathSourceList {
	switch {
	case engineName == "podman":
		return pathSourceList{Containers: []pathSource{}, Note: notePodman}
	case osErr != nil || psErr != nil:
		return pathSourceList{Containers: []pathSource{}, Note: noteNoEngine}
	case isDockerDesktop(osName):
		return pathSourceList{Containers: []pathSource{}, Note: noteDesktop}
	}
	sources := []pathSource{}
	for _, c := range cs {
		if c.State != "running" || !docker.IsContainerID(c.ID) {
			continue
		}
		name := engineText(c.Name)
		if name == "" {
			continue
		}
		sources = append(sources, pathSource{ID: c.ID, Name: name, Image: engineText(c.Image)})
	}
	if len(sources) == 0 {
		return pathSourceList{Containers: sources, Note: noteNoContainer}
	}
	slices.SortStableFunc(sources, func(a, b pathSource) int { return strings.Compare(a.Name, b.Name) })
	return pathSourceList{Containers: sources}
}

// isDockerDesktop reports whether the engine's OS name is Docker Desktop's VM.
func isDockerDesktop(osName string) bool {
	return strings.HasPrefix(osName, dockerDesktopName)
}

// engineText makes a string an engine returned safe to display: valid UTF-8,
// no escape sequence, no control or format rune, whitespace runs collapsed to
// one space, at most engineTextMaxRunes runes.
func engineText(s string) string {
	s = ansi.Strip(strings.ToValidUTF8(s, ""))
	var b strings.Builder
	pendingSpace := false
	for _, r := range s {
		switch {
		case unicode.IsSpace(r):
			pendingSpace = b.Len() > 0
			continue
		case unicode.Is(unicode.Cc, r) || unicode.Is(unicode.Cf, r):
			continue
		}
		if pendingSpace {
			b.WriteByte(' ')
			pendingSpace = false
		}
		b.WriteRune(r)
	}
	out := []rune(b.String())
	if len(out) > engineTextMaxRunes {
		out = out[:engineTextMaxRunes]
	}
	return strings.TrimRight(string(out), " ")
}

package netdiag

import (
	"strings"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/overlay"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

const (
	// reasonSourceRunning is the refusal of the selector key while a trace runs.
	reasonSourceRunning = "A path trace is running — esc cancels it"

	// textReadingSources is the footer state while the selector's list loads.
	textReadingSources = "Reading running containers..."

	// pickerTopRow is the body row the selector starts on: the table's header
	// row stays visible above it.
	pickerTopRow = 1
)

// sourceChoosable is the one answer to "can the selector open here", read by
// the header and by the handler (Rule 130).
func (pm *PathModel) sourceChoosable() shortcut.Availability {
	if pm.running() {
		return shortcut.Unavailable(reasonSourceRunning)
	}
	return pm.launchable()
}

// openPicker opens the selector and asks for its list. The engine is read by
// the Cmd only (Rule 110); the answer comes back as a pathSourcesMsg.
func (pm *PathModel) openPicker() (*PathModel, tea.Cmd) {
	if a := pm.sourceChoosable(); !a.Enabled() {
		return pm, pm.footer.Warn(a.Reason)
	}
	pm.sourcesGen++
	p := newPathSourcePicker(pm.source)
	pm.picker = &p
	return pm, loadPathSourcesCmd(pm.sourcesGen, pm.resolveTimeout, pm.engine)
}

// handleSources fills the selector. An answer to an older request, or one that
// arrives after the selector closed, changes nothing.
func (pm *PathModel) handleSources(msg pathSourcesMsg) (*PathModel, tea.Cmd) {
	if pm.picker == nil || msg.gen != pm.sourcesGen {
		return pm, nil
	}
	p := pm.picker.withList(msg.list)
	pm.picker = &p
	return pm, nil
}

// handlePickerKey gives the open selector every key: nothing reaches the field
// or the tab row.
func (pm *PathModel) handlePickerKey(key string) (*PathModel, tea.Cmd) {
	switch key {
	case "enter":
		return pm.chooseSource()
	case "esc":
		pm.picker = nil
	default:
		p := pm.picker.move(key, pickerRows(pm.pickerHeight()))
		pm.picker = &p
	}
	return pm, nil
}

// chooseSource closes the selector on the entry under the cursor. Choosing the
// source in use changes nothing; another one empties the column and returns to
// editing, the target value kept.
func (pm *PathModel) chooseSource() (*PathModel, tea.Cmd) {
	chosen := pm.picker.selected()
	pm.picker = nil
	if chosen.ID == pm.source.ID {
		return pm, nil
	}
	pm.source = chosen
	pm.target = pathTarget{}
	pm.clearRun()
	pm.state = pathEditing
	return pm, pm.input.Focus()
}

// pickerHeight is the room the selector has: the body below the header row.
func (pm *PathModel) pickerHeight() int { return pm.height - pickerTopRow }

// pickerRows is how many entries fit in height lines, borders excluded.
func pickerRows(height int) int { return max(height-pickerFrameRows, 1) }

// pickerStatus is the footer state while the selector is open: the loading
// dot, then the note that explains a list reduced to this machine (Rule 128).
func (pm *PathModel) pickerStatus() components.Status {
	if pm.picker.loading {
		return components.Status{Text: textReadingSources, Activity: true}
	}
	return components.Status{Text: pm.picker.note}
}

// viewWithPicker draws the selector over the table, which stays the body
// (Rules 112, 139).
func (pm *PathModel) viewWithPicker(body string) string {
	width := pm.table.RenderedWidth()
	box := pm.picker.render(width, pm.pickerHeight())
	x := max((width-pickerBoxWidth(width))/2, 0)
	return strings.Join(overlay.Compose(strings.Split(body, "\n"), box, x, pickerTopRow, width), "\n")
}

package netdiag

import (
	"strings"

	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	pickerTitle       = "Trace from"
	pickerEllipsis    = "…"
	pickerCurrentMark = " (current)"
	pickerImageSep    = " · "
	pickerMinBox      = 20
	pickerMaxBox      = 60
	pickerSideMargin  = 4 // cells of the terminal left around the box
	pickerFrameRows   = 2 // top and bottom borders
)

// pathSourcePicker is the "Trace from" selector: a value type with no I/O.
// Every method returns a new value; the table stays the body (Rule 139) and
// the caller draws these lines over it. Loading and notes belong to the footer
// (Rule 128), so they never appear in render.
type pathSourcePicker struct {
	sources []pathSource // this machine first
	current string       // ID of the source in use ("" = this machine)
	cursor  int
	top     int
	loading bool
	note    string
}

// newPathSourcePicker returns a picker offering only this machine, still
// waiting for the container list.
func newPathSourcePicker(current pathSource) pathSourcePicker {
	return pathSourcePicker{
		sources: []pathSource{hostSource()},
		current: current.ID,
		loading: true,
	}
}

// withList returns the picker with the containers of l after this machine. The
// cursor lands on the current source, or on this machine when it is gone.
func (p pathSourcePicker) withList(l pathSourceList) pathSourcePicker {
	p.sources = append([]pathSource{hostSource()}, l.Containers...)
	p.cursor = 0
	for i, s := range p.sources {
		if s.ID == p.current {
			p.cursor = i
			break
		}
	}
	p.top = 0
	p.loading = false
	p.note = l.Note
	return p
}

// move applies a navigation key with rows visible lines and returns the new
// picker. Keys that are not navigation leave it unchanged.
func (p pathSourcePicker) move(key string, rows int) pathSourcePicker {
	rows = max(rows, 1)
	last := len(p.sources) - 1
	switch key {
	case "up":
		p.cursor--
	case "down":
		p.cursor++
	case "pgup":
		p.cursor -= rows
	case "pgdown":
		p.cursor += rows
	case "home":
		p.cursor = 0
	case "end":
		p.cursor = last
	default:
		return p
	}
	p.cursor = min(max(p.cursor, 0), max(last, 0))
	p.top = p.window(rows)
	return p
}

// window returns the first visible index for rows lines, keeping the cursor in
// view while moving as little as possible. top is also capped so a window that
// grew never leaves blank room below the last entry.
func (p pathSourcePicker) window(rows int) int {
	top := min(p.top, p.cursor)
	if p.cursor >= top+rows {
		top = p.cursor - rows + 1
	}
	return max(min(top, len(p.sources)-rows), 0)
}

// selected returns the source under the cursor.
func (p pathSourcePicker) selected() pathSource {
	if p.cursor < 0 || p.cursor >= len(p.sources) {
		return hostSource()
	}
	return p.sources[p.cursor]
}

// render returns the framed selector, one string per line, each exactly
// pickerBoxWidth(width) cells wide. height is the room available, borders
// included.
func (p pathSourcePicker) render(width, height int) []string {
	box := pickerBoxWidth(width)
	inner := box - 2
	rows := min(len(p.sources), max(height-pickerFrameRows, 1))
	top := p.window(rows)

	border := lipgloss.NewStyle().Foreground(theme.ColorPaletteBorder).Background(theme.ColorBackground)
	lines := make([]string, 0, rows+pickerFrameRows)
	lines = append(lines, pickerTopBorder(inner, border))
	for i := top; i < top+rows && i < len(p.sources); i++ {
		lines = append(lines, border.Render("│")+p.renderRow(i, inner)+border.Render("│"))
	}
	return append(lines, border.Render("└"+strings.Repeat("─", inner)+"┘"))
}

// pickerTopBorder draws ┌─ Trace from ───┐ in inner+2 cells.
func pickerTopBorder(inner int, border lipgloss.Style) string {
	dashes := max(inner-ansi.StringWidth(pickerTitle)-3, 0)
	return border.Render("┌─ " + pickerTitle + " " + strings.Repeat("─", dashes) + "┐")
}

// renderRow draws one entry padded to inner cells; the cursor row carries the
// focus mark and the highlight colour.
func (p pathSourcePicker) renderRow(i, inner int) string {
	s := p.sources[i]
	prefix, color := "  ", theme.ColorText
	if i == p.cursor {
		prefix, color = theme.IconCircleSmall+" ", theme.ColorHighlight
	}
	text := prefix + s.label()
	if s.ID == p.current {
		text += pickerCurrentMark
	}
	if !s.isHost() && s.Image != "" {
		text += pickerImageSep + s.Image
	}
	text = ansi.Truncate(text, inner, pickerEllipsis)
	text += strings.Repeat(" ", max(inner-ansi.StringWidth(text), 0))
	return lipgloss.NewStyle().Foreground(color).Background(theme.ColorBackground).Render(text)
}

// pickerBoxWidth is the frame width: the terminal width minus a margin, kept
// between pickerMinBox and pickerMaxBox.
func pickerBoxWidth(width int) int {
	return min(max(width-pickerSideMargin, pickerMinBox), pickerMaxBox)
}

