2	
3	import (
4		"slices"
5		"strings"
6		"unicode"
7	
8		"github.com/charmbracelet/x/ansi"
9	
10		"github.com/anthnel/devdesk/internal/docker"
11	)
12	
13	const (
14		noteNoContainer = "No running container — only this machine is offered"
15		noteNoEngine    = "No Docker Engine reachable — only this machine is offered"
16		noteDesktop     = "Docker Desktop is not supported as a container source yet"
17		notePodman      = "podman is not supported as a container source"
18	
19		hostLabel          = "this machine"
20		engineTextMaxRunes = 128
21		dockerDesktopName  = "Docker Desktop"
22	)
23	
24	// pathSource is where a path trace starts: this machine or a container.
25	type pathSource struct {
26		ID    string // validated container ID; "" for this machine
27		Name  string // display-safe
28		Image string // display-safe
29	}
30	
31	// hostSource returns the source that stands for this machine.
32	func hostSource() pathSource { return pathSource{} }
33	
34	func (s pathSource) isHost() bool { return s.ID == "" }
35	
36	// label is the text the selector and the table show for the source.
37	func (s pathSource) label() string {
38		if s.isHost() {
39			return hostLabel
40		}
41		return s.Name
42	}
43	
44	// pathSourceList is what the selector offers besides this machine.
45	type pathSourceList struct {
46		Containers []pathSource // running, sorted by Name; this machine is not in it
47		Note       string       // why only this machine is offered; "" otherwise
48	}
49	
50	// sourceListFrom builds the selector's list from what the engine answered.
51	// Precedence: podman, then any read error, then Docker Desktop, then the list.
52	func sourceListFrom(engineName, osName string, osErr error, cs []docker.Container, psErr error) pathSourceList {
53		switch {
54		case engineName == "podman":
55			return pathSourceList{Containers: []pathSource{}, Note: notePodman}
56		case osErr != nil || psErr != nil:
57			return pathSourceList{Containers: []pathSource{}, Note: noteNoEngine}
58		case isDockerDesktop(osName):
59			return pathSourceList{Containers: []pathSource{}, Note: noteDesktop}
60		}
61		sources := []pathSource{}
62		for _, c := range cs {
63			if c.State != "running" || !docker.IsContainerID(c.ID) {
64				continue
65			}
66			name := engineText(c.Name)
67			if name == "" {
68				continue
69			}
70			sources = append(sources, pathSource{ID: c.ID, Name: name, Image: engineText(c.Image)})
71		}
72		if len(sources) == 0 {
73			return pathSourceList{Containers: sources, Note: noteNoContainer}
74		}
75		slices.SortStableFunc(sources, func(a, b pathSource) int { return strings.Compare(a.Name, b.Name) })
76		return pathSourceList{Containers: sources}
77	}
78	
79	// isDockerDesktop reports whether the engine's OS name is Docker Desktop's VM.
80	func isDockerDesktop(osName string) bool {
81		return strings.HasPrefix(osName, dockerDesktopName)
82	}
83	
84	// engineText makes a string an engine returned safe to display: valid UTF-8,
85	// no escape sequence, no control or format rune, whitespace runs collapsed to
86	// one space, at most engineTextMaxRunes runes.
87	func engineText(s string) string {
88		s = ansi.Strip(strings.ToValidUTF8(s, ""))
89		var b strings.Builder
90		pendingSpace := false
91		for _, r := range s {
92			switch {
93			case unicode.IsSpace(r):
94				pendingSpace = b.Len() > 0
95				continue
96			case unicode.Is(unicode.Cc, r) || unicode.Is(unicode.Cf, r):
97				continue
98			}
99			if pendingSpace {
100				b.WriteByte(' ')
101				pendingSpace = false
102			}
103			b.WriteRune(r)
104		}
105		out := []rune(b.String())
106		if len(out) > engineTextMaxRunes {
107			out = out[:engineTextMaxRunes]
108		}
109		return strings.TrimRight(string(out), " ")
110	}
